    const val RESULT_WIDTH_AT = 0
    const val RESULT_HEIGHT_AT = 4
    const val RESULT_FIRST_BASELINE_AT = 8
    const val RESULT_LAST_BASELINE_AT = 12
    const val RESULT_LAST_LINE_WIDTH_AT = 16
    const val RESULT_LINE_COUNT_AT = 20
    const val RESULT_FLAGS_AT = 24
    const val RESULT_STATUS_AT = 28
    const val FLAG_TRUNCATED = 1
    const val STATUS_OK = 0
    const val STATUS_UNKNOWN_NODE = 1
    const val STATUS_MALFORMED = 2
    const val CALL_OK = 0
    const val CALL_UNREADABLE = -1
    const val CALL_OFF_UI_THREAD = -4
    const val CALL_UNAVAILABLE = -5
}

sealed interface Modifier {
    data object Empty : Modifier
    data class Padding(val value: kotlin.Float) : Modifier
    data object FillMaxWidth : Modifier
    data object FillMaxHeight : Modifier
    data class Width(val value: kotlin.Float) : Modifier
    data class Height(val value: kotlin.Float) : Modifier
    data class Size(val width: kotlin.Float, val height: kotlin.Float) : Modifier
    data class Background(val paint: Paint) : Modifier
    data class Clickable(val handlerId: Long) : Modifier
    data class PaddingRole(val role: dev.darkpyonix.composerust.protocol.SpaceRole) : Modifier
    data class PaddingEach(val start: kotlin.Float, val top: kotlin.Float, val end: kotlin.Float, val bottom: kotlin.Float) : Modifier
    data class Weight(val value: kotlin.Float) : Modifier
    data class Shape(val topStart: kotlin.Float, val topEnd: kotlin.Float, val bottomEnd: kotlin.Float, val bottomStart: kotlin.Float) : Modifier
    data class ShapeRole(val role: dev.darkpyonix.composerust.protocol.ShapeRole) : Modifier
    data class Border(val width: kotlin.Float, val paint: Paint) : Modifier
    data class Elevation(val value: kotlin.Float) : Modifier
    data class ObserveSize(val token: Int) : Modifier
    data class Motion(val role: dev.darkpyonix.composerust.protocol.MotionRole) : Modifier
    data class Material(val role: dev.darkpyonix.composerust.protocol.MaterialRole) : Modifier
}

sealed interface Mutation {
    data class Create(val nodeId: Int, val widget: WidgetKind) : Mutation
    data class SetProp(val nodeId: Int, val property: PropertyKind, val value: PropertyValue) : Mutation
    data class SetModifier(val nodeId: Int, val index: Int, val modifier: Modifier) : Mutation
    data class Insert(val parentId: Int, val nodeId: Int, val index: Int) : Mutation
    data class Move(val parentId: Int, val nodeId: Int, val index: Int) : Mutation
    data class Remove(val nodeId: Int) : Mutation
    data class SetText(val nodeId: Int, val text: String, val selectionStart: Int, val selectionEnd: Int) : Mutation
    data class AppendText(val nodeId: Int, val text: String) : Mutation
    data class SetTheme(val theme: Theme) : Mutation
    data class SetWindow(val window: Window) : Mutation

    /**
     * The bytes of one asset. `kind` is the raw wire tag rather than an [AssetKind],
     * because a kind this Renderer cannot read has to be reported as a protocol error by
     * the asset cache instead of stopping the rest of the batch from being applied.
     *
     * `bytes` is already a copy: the batch buffer is only valid for the call that carried
     * it, and an asset has to outlive the frame that draws it.
     */
    data class RegisterAsset(val assetId: Int, val kind: Int, val bytes: ByteArray) : Mutation {
        override fun equals(other: Any?): Boolean =
            this === other ||
                (other is RegisterAsset && assetId == other.assetId && kind == other.kind &&
                    bytes.contentEquals(other.bytes))

        override fun hashCode(): Int =
            (assetId * 31 + kind) * 31 + bytes.contentHashCode()
    }

    data class ReleaseAsset(val assetId: Int) : Mutation

    /**
     * One sentence to say to the user, with an optional thing to do about it.
     *
     * It names no node because it is not in the tree. The Host says it once; how long it
     * stays, where it sits and what happens when a second one arrives while the first is
     * still up are the Renderer's to decide.
     *
     * `handlerId` is 0 when the message has no action, and `action` is then empty.
     */
    data class ShowMessage(
        val handlerId: Long,
        val text: String,
        val action: String,
        val duration: MessageDuration,
    ) : Mutation

    /**
     * One notification to show outside the window.
     *
     * Not a node: it outlives the component that posted it, and when it goes away is up to
     * the user in the notification centre. Posting again under the same `key` replaces it;
     * an empty `key` is named by the Renderer and can be neither replaced nor withdrawn. An
     * empty action label is no button.
     */
    data class PostNotification(
        val key: String,
        val title: String,
        val body: String,
        val channel: String,
        val action1: String,
        val action2: String,
        val importance: NotificationImportance,
        val presentation: NotificationPresentation,
    ) : Mutation

    /** Takes back the notification posted under `key`, if it is still showing. */
    data class WithdrawNotification(val key: String) : Mutation

    /** Asks the platform for permission. The answer comes back as an event. */
    data object RequestNotificationPermission : Mutation
}

sealed interface HostEvent {
    val nodeId: Int
    val handlerId: Long

    data class Clicked(override val nodeId: Int, override val handlerId: Long) : HostEvent
    data class TextChanged(override val nodeId: Int, override val handlerId: Long, val text: String) : HostEvent
    data class TextSubmitted(override val nodeId: Int, override val handlerId: Long, val text: String) : HostEvent
    data class FocusLost(override val nodeId: Int, override val handlerId: Long) : HostEvent
    data class ProtocolError(override val nodeId: Int, override val handlerId: Long, val code: Int, val message: String) : HostEvent
    data class KeyDown(override val nodeId: Int, override val handlerId: Long, val key: Key, val shiftKey: Boolean, val ctrlKey: Boolean, val altKey: Boolean, val metaKey: Boolean) : HostEvent
    data class RangeRequested(override val nodeId: Int, override val handlerId: Long, val start: Int, val count: Int) : HostEvent
    data class ValueChanged(override val nodeId: Int, override val handlerId: Long, val value: Double) : HostEvent
    data class WindowSizeChanged(override val nodeId: Int, override val handlerId: Long, val widthDp: kotlin.Float, val heightDp: kotlin.Float, val sizeClass: WindowSizeClass, val heightClass: WindowHeightClass) : HostEvent
    data class Resync(override val nodeId: Int, override val handlerId: Long) : HostEvent
    data class LifecycleStart(override val nodeId: Int, override val handlerId: Long) : HostEvent
    data class LifecycleStop(override val nodeId: Int, override val handlerId: Long) : HostEvent
    data class DesignSystemResolved(override val nodeId: Int, override val handlerId: Long, val system: DesignSystem) : HostEvent
    data class FilesEntered(override val nodeId: Int, override val handlerId: Long) : HostEvent
    data class FilesDropped(override val nodeId: Int, override val handlerId: Long, val text: String) : HostEvent
    data class NotificationActivated(override val nodeId: Int, override val handlerId: Long, val action: Int, val key: String) : HostEvent
    data class NotificationPermissionChanged(override val nodeId: Int, override val handlerId: Long, val state: NotificationPermission) : HostEvent
}

class ProtocolException(message: String, val offset: Int) :
    IllegalArgumentException("$message at byte offset $offset")

object Protocol {
    const val SCHEMA_HASH: Long = -794855757488596421L
    const val PROTOCOL_VERSION: Int = 1

    private const val TAG_ENVELOPE = 0
    private const val TAG_CREATE = 1
    private const val TAG_SET_PROP = 2
    private const val TAG_SET_MODIFIER = 3
    private const val TAG_INSERT = 4
    private const val TAG_MOVE = 5
    private const val TAG_REMOVE = 6
    private const val TAG_SET_TEXT = 7
    private const val TAG_APPEND_TEXT = 8
    private const val TAG_SET_THEME = 9
    private const val TAG_REGISTER_ASSET = 10
    private const val TAG_RELEASE_ASSET = 11
    private const val TAG_SHOW_MESSAGE = 12
    private const val TAG_SET_WINDOW = 13
    private const val TAG_POST_NOTIFICATION = 14
    private const val TAG_WITHDRAW_NOTIFICATION = 15
    private const val TAG_REQUEST_NOTIFICATION_PERMISSION = 16
    private const val ENVELOPE_LENGTH = 12
    /** Four role tags, one font asset id per type role, then the palette's reference. */
    private val THEME_RECORD_LENGTH = 20 + 4 * TypeRole.entries.size

    /** Bytes of one palette entry: a role tag, a scheme tag and a colour. */
    const val PALETTE_ENTRY_LENGTH = 8

    /**
     * The high bit of each of eight bytes, which is where UTF-8 stops being ASCII. Written
     * as a negative literal because 0x8080808080808080 does not fit a signed `Long`; the
     * bits are what matter and they are the same either way.
     */
    private const val ASCII_HIGH_BITS = -0x7f7f7f7f7f7f7f80L

    private const val VALUE_NONE = 0
    private const val VALUE_TEXT = 1
    private const val VALUE_BOOL = 2
    private const val VALUE_INTEGER = 3
    private const val VALUE_FLOAT = 4
    private const val VALUE_BYTES = 5

    /** Decodes a batch in place. Must not copy the buffer; only strings become Kotlin Strings. */
    fun decode(batch: ByteBuffer, onMutation: (Mutation) -> Unit) {
        val base = batch.position()
        val available = batch.remaining()
        val previousOrder = batch.order()
        batch.order(ByteOrder.LITTLE_ENDIAN)
        try {
            requireRange(available, 0, ENVELOPE_LENGTH, 0)
            if (readU16(batch, base, available, 0) != TAG_ENVELOPE ||
                readU16(batch, base, available, 2) != ENVELOPE_LENGTH
            ) {
                throw ProtocolException("invalid batch envelope", 0)
            }
            val recordsLengthLong = readU32(batch, base, available, 4)
            val countLong = readU32(batch, base, available, 8)
            if (recordsLengthLong < ENVELOPE_LENGTH ||
                recordsLengthLong > available.toLong() ||
                recordsLengthLong % 4L != 0L
            ) {
                throw ProtocolException("invalid records length", 4)
            }
            if (countLong > Int.MAX_VALUE.toLong()) {
                throw ProtocolException("record count is too large", 8)
            }
            val recordsLength = recordsLengthLong.toInt()
            val count = countLong.toInt()
            var offset = ENVELOPE_LENGTH
            var decoded = 0
            while (offset < recordsLength) {
                requireRange(recordsLength, offset, 4, offset)
                val tag = readU16(batch, base, available, offset)
                val length = readU16(batch, base, available, offset + 2)
                if (length < 4 || length % 4 != 0 || offset.toLong() + length > recordsLength) {
                    throw ProtocolException("invalid record length", offset + 2)
                }
                val mutation = when (tag) {
                    TAG_CREATE -> {
                        requireRecordLength(length, 12, offset)
                        Mutation.Create(
                            readU32(batch, base, available, offset + 4).toInt(),
                            widgetKind(readU16(batch, base, available, offset + 8), offset + 8),
                        )
                    }
                    TAG_SET_PROP -> {
                        requireRecordLength(length, 24, offset)
                        val value = when (val valueKind = readU16(batch, base, available, offset + 10)) {
                            VALUE_NONE -> PropertyValue.None
                            VALUE_TEXT -> PropertyValue.Text(readString(batch, base, available, offset + 12))
                            VALUE_BOOL -> PropertyValue.Bool(readU64(batch, base, available, offset + 12) != 0L)
                            VALUE_INTEGER -> PropertyValue.Integer(readU64(batch, base, available, offset + 12))
                            VALUE_FLOAT -> PropertyValue.Float(
                                kotlin.Float.fromBits(readU64(batch, base, available, offset + 12).toInt()),
                            )
                            VALUE_BYTES -> PropertyValue.Bytes(readBytes(batch, base, available, offset + 12))
                            else -> throw ProtocolException("unknown property value tag $valueKind", offset + 10)
                        }
                        Mutation.SetProp(
                            readU32(batch, base, available, offset + 4).toInt(),
                            propertyKind(readU16(batch, base, available, offset + 8), offset + 8),
                            value,
                        )
                    }
                    TAG_SET_MODIFIER -> {
                        requireRecordLength(length, 28, offset)
                        Mutation.SetModifier(
                            readU32(batch, base, available, offset + 4).toInt(),
                            readU16(batch, base, available, offset + 8),
                            modifier(
                                readU16(batch, base, available, offset + 10),
                                readU64(batch, base, available, offset + 12),
                                readU64(batch, base, available, offset + 20),
                                offset + 10,
                            ),
                        )
                    }
                    TAG_INSERT -> {
                        requireRecordLength(length, 16, offset)
                        Mutation.Insert(
                            readU32(batch, base, available, offset + 4).toInt(),
                            readU32(batch, base, available, offset + 8).toInt(),
                            readU32(batch, base, available, offset + 12).toInt(),
                        )
                    }
                    TAG_MOVE -> {
                        requireRecordLength(length, 16, offset)
                        Mutation.Move(
                            readU32(batch, base, available, offset + 4).toInt(),
                            readU32(batch, base, available, offset + 8).toInt(),
                            readU32(batch, base, available, offset + 12).toInt(),
                        )
                    }
                    TAG_REMOVE -> {
                        requireRecordLength(length, 8, offset)
                        Mutation.Remove(readU32(batch, base, available, offset + 4).toInt())
                    }
                    TAG_SET_TEXT -> {
                        requireRecordLength(length, 24, offset)
                        Mutation.SetText(
                            readU32(batch, base, available, offset + 4).toInt(),
                            readString(batch, base, available, offset + 8),
                            readU32(batch, base, available, offset + 16).toInt(),
                            readU32(batch, base, available, offset + 20).toInt(),
                        )
                    }
                    TAG_APPEND_TEXT -> {
                        requireRecordLength(length, 16, offset)
                        Mutation.AppendText(
                            readU32(batch, base, available, offset + 4).toInt(),
                            readString(batch, base, available, offset + 8),
                        )
                    }
                    TAG_SET_THEME -> {
                        requireRecordLength(length, THEME_RECORD_LENGTH, offset)
                        val adaptive = readU16(batch, base, available, offset + 10)
                        if (adaptive > 1) {
                            throw ProtocolException("invalid adaptive flag $adaptive", offset + 10)
                        }
                        // One slot per type role, in the order the wire fixes them in.
                        val fonts = List(TypeRole.entries.size) { role ->
                            readU32(batch, base, available, offset + 12 + 4 * role).toInt()
                        }
                        val (entries, problems) = palette(
                            readBytes(batch, base, available, offset + 12 + 4 * TypeRole.entries.size),
                        )
                        Mutation.SetTheme(
                            Theme(
                                designSystem(readU16(batch, base, available, offset + 4), offset + 4),
                                designSystem(readU16(batch, base, available, offset + 6), offset + 6),
                                colorScheme(readU16(batch, base, available, offset + 8), offset + 8),
                                adaptive == 1,
                                fonts,
                                entries,
                                problems,
                            ),
                        )
                    }
                    TAG_SET_WINDOW -> {
                        requireRecordLength(length, 32, offset)
                        val resizable = readU16(batch, base, available, offset + 16)
                        if (resizable > 1) {
                            throw ProtocolException("invalid resizable flag $resizable", offset + 16)
                        }
                        Mutation.SetWindow(
                            Window(
                                chrome(readU16(batch, base, available, offset + 4), offset + 4),
                                titleBar(readU16(batch, base, available, offset + 6), offset + 6),
                                readString(batch, base, available, offset + 20),
                                readU32(batch, base, available, offset + 28).toInt(),
                                readU16(batch, base, available, offset + 8),
                                readU16(batch, base, available, offset + 10),
                                readU16(batch, base, available, offset + 12),
                                readU16(batch, base, available, offset + 14),
                                resizable == 1,
                            ),
                        )
                    }
                    TAG_REGISTER_ASSET -> {
                        requireRecordLength(length, 20, offset)
                        Mutation.RegisterAsset(
                            readU32(batch, base, available, offset + 4).toInt(),
                            readU16(batch, base, available, offset + 8),
                            readBytes(batch, base, available, offset + 12),
                        )
                    }
                    TAG_RELEASE_ASSET -> {
                        requireRecordLength(length, 8, offset)
                        Mutation.ReleaseAsset(readU32(batch, base, available, offset + 4).toInt())
                    }
                    TAG_SHOW_MESSAGE -> {
                        requireRecordLength(length, 32, offset)
                        Mutation.ShowMessage(
                            readU64(batch, base, available, offset + 4),
                            readString(batch, base, available, offset + 12),
                            readString(batch, base, available, offset + 20),
                            messageDuration(readU16(batch, base, available, offset + 28), offset + 28),
                        )
                    }
                    TAG_POST_NOTIFICATION -> {
                        requireRecordLength(length, 56, offset)
                        Mutation.PostNotification(
                            readString(batch, base, available, offset + 4),
                            readString(batch, base, available, offset + 12),
                            readString(batch, base, available, offset + 20),
                            readString(batch, base, available, offset + 28),
                            readString(batch, base, available, offset + 36),
                            readString(batch, base, available, offset + 44),
                            notificationImportance(readU16(batch, base, available, offset + 52), offset + 52),
                            notificationPresentation(readU16(batch, base, available, offset + 54), offset + 54),
                        )
                    }
                    TAG_WITHDRAW_NOTIFICATION -> {
                        requireRecordLength(length, 12, offset)
                        Mutation.WithdrawNotification(readString(batch, base, available, offset + 4))
                    }
                    TAG_REQUEST_NOTIFICATION_PERMISSION -> {
                        requireRecordLength(length, 4, offset)
                        Mutation.RequestNotificationPermission
                    }
                    else -> throw ProtocolException("unknown mutation tag $tag", offset)
                }
                onMutation(mutation)
                decoded += 1
                offset += length
            }
            if (offset != recordsLength || decoded != count) {
                throw ProtocolException("record count does not match envelope", offset)
            }
        } finally {
            batch.order(previousOrder)
        }
    }

    /**
     * Reads a palette, keeping every sound entry and saying what was wrong with the rest.
     *
     * Lenient on purpose, unlike the rest of the batch: an unknown role, a scheme that is
     * neither light nor dark, a second value for the same role and scheme, or a length
     * that is not a whole number of entries is one entry's fault, and the others are
     * still what the application asked for.
     */
    fun palette(bytes: ByteArray): Pair<List<PaletteEntry>, List<String>> {
        if (bytes.isEmpty()) return emptyList<PaletteEntry>() to emptyList()
        val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        val entries = ArrayList<PaletteEntry>(bytes.size / PALETTE_ENTRY_LENGTH)
        val problems = ArrayList<String>()
        if (bytes.size % PALETTE_ENTRY_LENGTH != 0) {
            problems += "a palette of ${bytes.size} bytes is not a whole number of " +
                "$PALETTE_ENTRY_LENGTH byte entries; the bytes past the last whole one are ignored"
        }
        for (index in 0 until bytes.size / PALETTE_ENTRY_LENGTH) {
            val at = index * PALETTE_ENTRY_LENGTH
            val roleTag = buffer.getShort(at).toInt() and 0xffff
            val schemeTag = buffer.getShort(at + 2).toInt() and 0xffff
            val argb = buffer.getInt(at + 4)
            val role = paletteRole(roleTag)
            if (role == null) {
                problems += "palette entry $index names colour role $roleTag, which does not exist"
                continue
            }
            val dark = when (schemeTag) {
                1 -> false
                2 -> true
                else -> {
                    problems += "palette entry $index gives $role for scheme $schemeTag; " +
                        "an entry is for light (1) or dark (2), and following the system is not a scheme"
                    continue
                }
            }
            if (entries.any { it.role == role && it.dark == dark }) {
                problems += "palette entry $index gives $role in ${if (dark) "dark" else "light"} " +
                    "a second time; the first value stands"
                continue
            }
            entries += PaletteEntry(role, dark, argb)
        }
        return entries to problems
    }

    /** Encodes one event into `out` (little-endian), returns bytes written. */
    fun encodeEvent(event: HostEvent, out: ByteBuffer): Int {
        val start = out.position()
        val previousOrder = out.order()
        out.order(ByteOrder.LITTLE_ENDIAN)
        try {
            val text = when (event) {
                is HostEvent.Clicked -> null
                is HostEvent.TextChanged -> event.text.toByteArray(StandardCharsets.UTF_8)
                is HostEvent.TextSubmitted -> event.text.toByteArray(StandardCharsets.UTF_8)
                is HostEvent.FocusLost -> null
                is HostEvent.ProtocolError -> event.message.toByteArray(StandardCharsets.UTF_8)
                is HostEvent.KeyDown -> null
                is HostEvent.RangeRequested -> null
                is HostEvent.ValueChanged -> null
                is HostEvent.WindowSizeChanged -> null
                is HostEvent.Resync -> null
                is HostEvent.LifecycleStart -> null
                is HostEvent.LifecycleStop -> null
                is HostEvent.DesignSystemResolved -> null
                is HostEvent.FilesEntered -> null
                is HostEvent.FilesDropped -> event.text.toByteArray(StandardCharsets.UTF_8)
                is HostEvent.NotificationActivated -> event.key.toByteArray(StandardCharsets.UTF_8)
                is HostEvent.NotificationPermissionChanged -> null
            }
            val recordLength = when (event) {
                is HostEvent.Clicked -> 16
                is HostEvent.TextChanged -> 24
                is HostEvent.TextSubmitted -> 24
                is HostEvent.FocusLost -> 16
                is HostEvent.ProtocolError -> 28
                is HostEvent.KeyDown -> 20
                is HostEvent.RangeRequested -> 24
                is HostEvent.ValueChanged -> 24
                is HostEvent.WindowSizeChanged -> 32
                is HostEvent.Resync -> 16
                is HostEvent.LifecycleStart -> 16
                is HostEvent.LifecycleStop -> 16
                is HostEvent.DesignSystemResolved -> 20
                is HostEvent.FilesEntered -> 16
                is HostEvent.FilesDropped -> 24
                is HostEvent.NotificationActivated -> 28
                is HostEvent.NotificationPermissionChanged -> 20
            }
            val totalLength = recordLength.toLong() + (text?.size ?: 0)
            if (totalLength > Int.MAX_VALUE || totalLength > out.remaining().toLong()) {
                throw ProtocolException("event output buffer is too small", 0)
            }
            val tag = when (event) {
                is HostEvent.Clicked -> 1
                is HostEvent.TextChanged -> 2
                is HostEvent.TextSubmitted -> 3
                is HostEvent.FocusLost -> 4
                is HostEvent.ProtocolError -> 5
                is HostEvent.KeyDown -> 6
                is HostEvent.RangeRequested -> 7
                is HostEvent.ValueChanged -> 16
                is HostEvent.WindowSizeChanged -> 17
                is HostEvent.Resync -> 18
                is HostEvent.LifecycleStart -> 19
                is HostEvent.LifecycleStop -> 20
                is HostEvent.DesignSystemResolved -> 21
                is HostEvent.FilesEntered -> 22
                is HostEvent.FilesDropped -> 23
                is HostEvent.NotificationActivated -> 24
                is HostEvent.NotificationPermissionChanged -> 25
            }
            out.putShort(tag.toShort())
            out.putShort(recordLength.toShort())
            out.putInt(event.nodeId)
            out.putLong(event.handlerId)
            when (event) {
                is HostEvent.Clicked -> Unit
                is HostEvent.TextChanged -> writeStringReference(out, recordLength, text!!)
                is HostEvent.TextSubmitted -> writeStringReference(out, recordLength, text!!)
                is HostEvent.FocusLost -> Unit
                is HostEvent.ProtocolError -> {
                    out.putInt(event.code)
                    writeStringReference(out, recordLength, text!!)
                }
                is HostEvent.KeyDown -> {
                    out.putShort(keyTag(event.key).toShort())
                    var modifiers = 0
                    if (event.shiftKey) modifiers = modifiers or 0x01
                    if (event.ctrlKey) modifiers = modifiers or 0x02
                    if (event.altKey) modifiers = modifiers or 0x04
                    if (event.metaKey) modifiers = modifiers or 0x08
                    out.put(modifiers.toByte())
                    out.put(0.toByte())
                }
                is HostEvent.RangeRequested -> {
                    out.putInt(event.start)
                    out.putInt(event.count)
                }
                is HostEvent.ValueChanged -> out.putDouble(event.value)
                is HostEvent.WindowSizeChanged -> {
                    out.putFloat(event.widthDp)
                    out.putFloat(event.heightDp)
                    out.putInt(windowSizeClassTag(event.sizeClass))
                    out.putInt(windowHeightClassTag(event.heightClass))
                }
                is HostEvent.Resync -> Unit
                is HostEvent.LifecycleStart -> Unit
                is HostEvent.LifecycleStop -> Unit
                is HostEvent.DesignSystemResolved -> {
                    out.putInt(designSystemTag(event.system))
                }
                is HostEvent.FilesEntered -> Unit
                is HostEvent.FilesDropped -> writeStringReference(out, recordLength, text!!)
                is HostEvent.NotificationActivated -> {
                    out.putInt(event.action)
                    writeStringReference(out, recordLength, text!!)
                }
                is HostEvent.NotificationPermissionChanged -> {
                    out.putInt(notificationPermissionTag(event.state))
                }
            }
            if (text != null) out.put(text)
            return out.position() - start
        } finally {
            out.order(previousOrder)
        }
    }

    /**
     * Handshake payload the Renderer sends to compose_rust_host_init.
     *
     * `loopMode` says who owns the frame loop: the Renderer on desktop, the platform on
     * Android, iOS and the web.
     */
    fun handshake(out: ByteBuffer, loopMode: LoopMode = LoopMode.Renderer): Int {
        val start = out.position()
        if (out.remaining() < 12) {
            throw ProtocolException("handshake output buffer is too small", 0)
        }
        val previousOrder = out.order()
        out.order(ByteOrder.LITTLE_ENDIAN)
        try {
            out.putLong(SCHEMA_HASH)
            out.putShort(PROTOCOL_VERSION.toShort())
            out.put(loopMode.wire)
            out.put(0.toByte()) // Reserved for alignment.
            return out.position() - start
        } finally {
            out.order(previousOrder)
        }
    }

    private fun writeStringReference(out: ByteBuffer, offset: Int, bytes: ByteArray) {
        out.putInt(offset)
        out.putInt(bytes.size)
    }

    private fun widgetKind(tag: Int, offset: Int): WidgetKind = when (tag) {
        1 -> WidgetKind.Column
        2 -> WidgetKind.Row
        3 -> WidgetKind.Box
        4 -> WidgetKind.Text
